import { Picker } from '@larose-ui/react';
import { useState } from 'react';

const columns = [
  {
    id: 'dept',
    label: 'Department',
    options: [
      { value: 'eng', label: 'Engineering' },
      { value: 'design', label: 'Design' },
      { value: 'sales', label: 'Sales' },
    ],
  },
];

export default function App() {
  const [value, setValue] = useState({ dept: 'eng' });
  return <Picker label="Department" columns={columns} value={value} onChange={setValue} />;
}
